  // CHECK THE STATUS. This POST is the one call whose silent failure is
  // invisible and self-perpetuating: `openMaintenancePull` reuses by OPEN PR,
  // so a cycle that pushes a branch but fails to open its PR mints a FRESH
  // branch the next cycle, and the next — branches pile up daily, the stamp
  // never advances, and the run still reports `ok`. That is exactly what the
  // fleet did for two days: every consumer but the pilot sat at the same
  // canon ref with 07-29 and 07-30 maintenance branches and no PR behind
  // either. The usual cause is repo-level: "Allow GitHub Actions to create
  // and approve pull requests" is off, and the POST 403s.
  const created = await gh(token, `/repos/${repo}/pulls`, {
    method: 'POST', body: { head: branch, base, title: 'Claudinite maintenance', body },
  });
  if (created.status !== 201 || !created.json?.number) {
    const detail = created.json?.message ?? `HTTP ${created.status}`;
    throw new Error(`could not open the maintenance PR for ${branch}: ${detail}`
      + ' — if this is the Actions PR permission, enable Settings → Actions → General →'
      + ' "Allow GitHub Actions to create and approve pull requests"');
  }
  pr = created.json;
}

